'use strict';
/* RAPID V5 QUALITY OPTIMIZER — fresh current-live reconstruction.
   75% DEV / 25% untouched HOLD. Core RR/SL/maxBars unchanged.
   Optimizes entry QUALITY only: H1 separation, M5 body, EMA distance, range cap,
   plus a few pre-identified weak-hour groups. Ranking uses DEV only.
*/
const fs=require('fs'),P='data/xauusd-m5-dukascopy.json';if(!fs.existsSync(P))throw Error('Missing '+P);
const M=JSON.parse(fs.readFileSync(P,'utf8')).map(x=>({t:+(x.timestamp??x.time),o:+(x.open??x.o),h:+(x.high??x.h),l:+(x.low??x.l),c:+(x.close??x.c)})).filter(x=>[x.t,x.o,x.h,x.l,x.c].every(Number.isFinite)).sort((a,b)=>a.t-b.t);
function ema(v,p){let o=Array(v.length).fill(NaN),e=v[0],k=2/(p+1);for(let i=0;i<v.length;i++){if(i)e=v[i]*k+e*(1-k);if(i>=p-1)o[i]=e}return o}function atr(c,p=14){let o=Array(c.length).fill(NaN),s=0;for(let i=1;i<c.length;i++){let tr=Math.max(c[i].h-c[i].l,Math.abs(c[i].h-c[i-1].c),Math.abs(c[i].l-c[i-1].c));s+=tr;if(i>p){let j=i-p,old=Math.max(c[j].h-c[j].l,Math.abs(c[j].h-c[j-1].c),Math.abs(c[j].l-c[j-1].c));s-=old}if(i>=p)o[i]=s/p}return o}
function h1(){let a=[],cur=null;for(const x of M){let d=new Date(x.t),t=Date.UTC(d.getUTCFullYear(),d.getUTCMonth(),d.getUTCDate(),d.getUTCHours());if(!cur||cur.t!==t){cur={t,o:x.o,h:x.h,l:x.l,c:x.c};a.push(cur)}else{cur.h=Math.max(cur.h,x.h);cur.l=Math.min(cur.l,x.l);cur.c=x.c}}return a}const H=h1(),MC=M.map(x=>x.c),ME=ema(MC,20),MA=atr(M),HC=H.map(x=>x.c),H20=ema(HC,20),H50=ema(HC,50),HA=atr(H);let hp=0;const hIndex=Array(M.length);for(let i=0;i<M.length;i++){while(hp+1<H.length&&H[hp+1].t<=M[i].t)hp++;hIndex[i]=Math.max(0,hp-1)}
function run(q){let out=[],pos=null;for(let i=60;i<M.length-1;i++){if(pos){let b=M[i],sl=pos.s==='BUY'?b.l<=pos.sl:b.h>=pos.sl,tp=pos.s==='BUY'?b.h>=pos.tp:b.l<=pos.tp;if(sl||tp||i-pos.ei+1>=10){let px=sl?pos.sl:tp?pos.tp:b.c,r=(pos.s==='BUY'?px-pos.en:pos.en-px)/pos.risk;out.push({t:M[pos.si].t,r,s:pos.s});pos=null}if(pos)continue}let h=hIndex[i],hr=new Date(M[i].t).getUTCHours();if([20,22].includes(hr)||q.block.includes(hr))continue;if(h<52||![ME[i],MA[i],H20[h],H50[h],HA[h],H20[h-2]].every(Number.isFinite)||!(MA[i]>0&&HA[h]>0))continue;let sep=Math.abs(H20[h]-H50[h])/HA[h];if(sep<q.sep)continue;let bull=HC[h]>H20[h]&&H20[h]>H50[h]&&H20[h]>H20[h-2],bear=HC[h]<H20[h]&&H20[h]<H50[h]&&H20[h]<H20[h-2];if(!bull&&!bear)continue;let hi=-Infinity,lo=Infinity;for(let j=i-3;j<i;j++){hi=Math.max(hi,M[j].h);lo=Math.min(lo,M[j].l)}let rg=M[i].h-M[i].l,body=Math.abs(M[i].c-M[i].o);if(!rg||body/MA[i]<q.body||rg/MA[i]>q.range)continue;let cp=(M[i].c-M[i].l)/rg;if(Math.abs(M[i].c-ME[i])/MA[i]>q.ema)continue;let buy=bull&&M[i].c>hi&&cp>=.72&&M[i].c>ME[i],sell=bear&&M[i].c<lo&&cp<=.28&&M[i].c<ME[i];if(!buy&&!sell)continue;let side=buy?'BUY':'SELL';if(side==='BUY'&&[3,16].includes(hr))continue;let entry=M[i+1].o,swing=side==='BUY'?Math.min(M[i].l,M[i-1].l):Math.max(M[i].h,M[i-1].h),risk=Math.max(MA[i]*.65,Math.abs(entry-swing));if(risk>MA[i]*1.35)continue;let rr=side==='BUY'?.85:.8;pos={s:side,en:entry,risk,sl:side==='BUY'?entry-risk:entry+risk,tp:side==='BUY'?entry+risk*rr:entry-risk*rr,ei:i+1,si:i}}return out}
function S(a){let gp=0,gl=0,w=0,e=0,p=0,dd=0,ls=0,mx=0;for(const x of a){e+=x.r;if(x.r>0){w++;gp+=x.r;ls=0}else{if(x.r<0)gl+=-x.r;ls++;mx=Math.max(mx,ls)}p=Math.max(p,e);dd=Math.max(dd,p-e)}return{n:a.length,wr:a.length?100*w/a.length:0,pf:gl?gp/gl:(gp?Infinity:0),net:e,dd,ls:mx}}const F=s=>`T${s.n} WR${s.wr.toFixed(1)} PF${s.pf===Infinity?'∞':s.pf.toFixed(2)} N${s.net>=0?'+':''}${s.net.toFixed(2)}R DD${s.dd.toFixed(2)} LS${s.ls}`;
const split=M[Math.floor(M.length*.75)].t,base={sep:.08,body:.65,ema:1.5,range:2,block:[]},bt=run(base),bd=S(bt.filter(x=>x.t<split)),bh=S(bt.filter(x=>x.t>=split));console.log('RAPID V5 — QUALITY OPTIMIZER');console.log('75% DEV / 25% HOLDOUT | current RR/SL/maxBars unchanged');console.log('Split',new Date(split).toISOString());console.log('\nBASE DEV ',F(bd));console.log('BASE HOLD',F(bh));
let rows=[],id=0;const blocks=[[],[2],[12],[2,12],[6,12],[2,6,12],[2,12,18],[2,6,12,18]];for(const block of blocks)for(const sep of [.08,.10,.12,.15,.18])for(const body of [.65,.72,.80,.90])for(const emaD of [1.5,1.25,1.0])for(const range of [2,1.8,1.6]){let c={id:++id,block,sep,body,ema:emaD,range},a=run(c),d=S(a.filter(x=>x.t<split)),h=S(a.filter(x=>x.t>=split));if(d.n<150||h.n<35||d.n/bd.n<.55)continue;let score=(d.pf-bd.pf)*2+(d.wr-bd.wr)/20+(bd.dd-d.dd)/5;rows.push({c,d,h,score})}rows.sort((a,b)=>b.score-a.score);console.log('\n🏆 TOP 20 — DEV RANKING; HOLD NEVER RANKED');for(const x of rows.slice(0,20)){let c=x.c;console.log(`#${c.id} block[${c.block.join(',')||'-'}] SEP>=${c.sep} BODY>=${c.body} EMA<=${c.ema} RANGE<=${c.range} | DEV ${F(x.d)} | HOLD ${F(x.h)}`)}console.log('\n🛡️ ROBUST SHORTLIST');let r=rows.filter(x=>x.h.pf>=bh.pf&&x.h.wr>=bh.wr&&x.h.dd<=bh.dd*1.1&&x.d.pf>bd.pf&&x.d.wr>=bd.wr).slice(0,15);if(!r.length)console.log('No strict robust candidate. Keep live unchanged.');else for(const x of r){let c=x.c;console.log(`#${c.id} block[${c.block.join(',')||'-'}] SEP>=${c.sep} BODY>=${c.body} EMA<=${c.ema} RANGE<=${c.range} | DEV ${F(x.d)} | HOLD ${F(x.h)}`)}